NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'II Corinthians'

CHAPTERS = {
    1: {
        1: 'Paulus, Jesu Kristi apostel ved Guds vilje, og broderen Timoteus til Guds kyrkjelyd som er i Korint, med alle dei heilage i heile Akaia:',
        2: 'Nåde vere med dykk og fred frå Gud, vår Fader, og Herren Jesus Kristus!',
        3: 'Lova vere Gud og vår Herre Jesu Kristi Fader, miskunns Fader og all trøystings Gud,',
        4: 'han som trøystar oss i all vår trengsla, so me kann trøysta deim som er i allslags trengsla, med den trøyst som me sjølve vert trøysta med av Gud!',
        5: 'For liksom Kristi lidingar kjem rikleg yver oss, so er og vår trøyst rikleg ved Kristus.',
        6: 'Men um me lid trengsla, so er det til dykkar trøyst og frelsa; vert me trøysta, so er det dykk til ei trøyst som viser seg verksam i tolmod i dei same lidingar som me lid;',
        7: 'og vår von um dykk er fast, av di me veit at liksom de hev lut i lidingarne, so skal de og hava lut i trøysti.',
        8: 'For me vil ikkje, brør, at de skal vera uvitande um den trengsla som kom yver oss i Asia, at me vart ovleg hardt nedtyngde, meir enn me kunde bera, so at me jamvel mistvila um livet;',
        9: 'ja, me hadde med oss sjølve gjort upp at me laut døy, so me ikkje skulde lita på oss sjølve, men på Gud, som vekkjer upp dei daude,',
        10: 'han som fria og friar oss frå slik daude, som me vonar og vil fria oss heretter,',
        11: 'med di de og kjem oss til hjelp med bøn, so det frå mange munnar må koma rikleg takk for oss, for den nåde som er oss gjeven.',
        12: 'For vår ros er dette: Vitnemålet i vårt samvit um at me i Guds heilagdom og reinleik, ikkje i kjøtleg visdom, men i Guds nåde hev ferdast i verdi, og serleg hjå dykk.',
        13: 'For me skriv ikkje anna til dykk enn det som de les eller skynar, og eg vonar at de og skal skyna det til enden',
        14: '- liksom de og til deils hev skyna oss - at me er dykkar ros, liksom de og er vår på Herren Jesu dag.',
        15: 'Og i denne tillit rådde eg meg til å koma til dykk fyrst, so de kunde få endå ein nåde,',
        16: 'og fara frå dykk til Makedonia, og so koma frå Makedonia til dykk att og få fylgje av dykk til Judæa.',
        17: 'Då eg no tok denne rådi, for eg då kann henda fram med lauslynde, eller er det etter kjøtet eg tek dei råder som eg tek, so det hjå meg skulde vera både ja, ja og nei, nei?',
        18: 'So visst som Gud er trufast, so er vårt ord til dykk ikkje ja og nei.',
        19: 'For Guds Son, Kristus Jesus, som vart forkynt hjå dykk ved oss, ved meg og Silvanus og Timoteus, han var ikkje ja og nei, men ja hev det vorte i honom.',
        20: 'For so mange som Guds lovnader er, so hev dei i honom sitt ja og fær og i honom sitt amen, Gud til æra ved oss.',
        21: 'Men den som held oss faste saman med dykk i Kristus og salva oss, det er Gud,',
        22: 'han som sette sitt innsigle på oss og gav Anden til pant i våre hjarto.',
        23: 'Men eg kallar Gud til vitne for mi sjæl, at det var for di eg vilde spara dykk at eg ikkje endå er komen til Korint;',
        24: 'ikkje at me er herrar yver dykkar tru, men me er medverkande til dykkar gleda; for de stend i trui.',
    },
    2: {
        1: 'Men eg sette meg fyre for mi eigi skuld, at eg ikkje atter vilde koma til dykk med sorg.',
        2: 'For um eg gjer dykk sorg, kven er det då som gjer meg glad, utan den som eg gjer sorg?',
        3: 'Og eg skreiv til dykk just difor, at eg ikkje, når eg kom, skulde få sorg av deim som eg skulde hava gleda av, då eg hev den tiltru til dykk alle, at mi gleda er gleda for dykk alle.',
        4: 'For i myki trengsla og hjartans tyngsla skreiv eg dykk til med mange tåror, ikkje for di at de skulde få sorg, men at de skulde kjenna den kjærleiken som eg serleg hev til dykk.',
        5: 'Men um nokon hev gjort sorg, so er det ikkje meg han hev gjort sorg, men til deils - at eg ikkje skal vera for hard - dykk alle.',
        6: 'Det er nok for honom med den refsingi han hev fenge av dei fleste,',
        7: 'so at de heller må tilgjeva og trøysta honom, so han ikkje skal ganga under i endå tyngre sorg.',
        8: 'Difor bed eg dykk at de må lata kjærleik råda mot honom.',
        9: 'For difor var det og eg skreiv, at eg skulde få vita um de held prøva, um de er lyduge i alt.',
        10: 'Men den som de tilgjev, honom tilgjev eg og. For det eg hev tilgjeve - um eg hev havt noko å tilgjeva - det hev eg gjort for dykkar skuld, for Kristi åsyn,',
        11: 'so me ikkje skal verta dåra av Satan; for me er ikkje uvitande um hans råder.',
        12: 'Då eg kom til Troas for Kristi evangelium skuld, og ei dør var opna for meg i Herren,',
        13: 'hadde eg ikkje ro i mi ånd, av di eg ikkje fann Titus, bror min, men eg skildest frå deim og for til Makedonia.',
        14: 'Men Gud vere takk, som alltid fører oss fram på sigerferd i Kristus og ved oss openberrar angen av kunnskapen um honom på kvar stad!',
        15: 'For me er Kristi huglege ange for Gud millom deim som vert frelste, og millom deim som vert fortapte,',
        16: 'for desse ein ange av daude til daude, for hine ein ange av liv til liv. Og kven er vel dugleg til dette?',
        17: 'For me er ikkje slike som dei mange, at me falskar Guds ord til eigi vinning, men som i reinleik, ja, som av Gud talar me for Guds åsyn i Kristus.',
    },
    3: {
        1: 'Byrjar me å gjeva oss sjølve lovord att? eller treng me då, liksom sume folk, til å hava lovords brev til dykk eller frå dykk?',
        2: 'De er vårt brev, innskrive i våre hjarto, kjent og lese av alle menneskje,',
        3: 'med di det er kunnigt at de er Kristi brev, tilkome ved vår tenesta, innskrive ikkje med blekk, men med den livande Guds Ande, ikkje på steintavlor, men på hjartans kjøttavlor.',
        4: 'Men ei slik tiltru hev me til Gud ved Kristus,',
        5: 'ikkje at me av oss sjølve duger til å tenkja ut noko som av oss sjølve, men dugleiken vår er av Gud,',
        6: 'han som og gjorde oss duglege til å vera tenarar for ei ny pakt, ikkje for bokstav, men for ande; for bokstaven slær i hel, men Anden gjer livande.',
        7: 'Når då daudens tenesta, som var innhoggi med bokstavar på steinar, kom med herlegdom, so Israels-borni ikkje greidde å sjå på Mose åsyn på grunn av herlegdomen i hans åsyn, endå det var ein som kvarv burt,',
        8: 'kor skal ikkje då Andens tenesta endå meir vera i herlegdom!',
        9: 'For er fordømings-tenesta herlegdom, so er rettferds-tenesta endå mykje meir rik på herlegdom.',
        10: 'For endå det herlege er i dette stykke ikkje herlegt mot den ovrike herlegdomen.',
        11: 'For når det burtkvervande var i herlegdom, so skal det vedvarande so mykje meir vera i herlegdom.',
        12: 'Sidan me då hev slik ei von, so gjeng me fram med stort frimod',
        13: 'og gjer ikkje som Moses, som lagde eit sveip yver si åsyn, so Israels-borni ikkje skulde skoda enden av det som kvarv burt.',
        14: 'Men deira hug vart forherd; for like til denne dag ligg det same sveipet der når dei les den gamle pakti, og det vert ikkje openberra at ho vert avlyst i Kristus.',
        15: 'Men til denne dag ligg det eit sveip yver hjarta deira når Moses vert lesen.',
        16: 'Men når det vender um til Herren, då vert sveipet burtteke.',
        17: 'Men Herren er Anden; men der Herrens Ande er, der er fridom.',
        18: 'Men me som med usveipt åsyn ser Herrens herlegdom som i ein spegel, me vert alle umlaga til det same bilæte frå herlegdom til herlegdom, liksom av Herrens Ande.',
    },
    4: {
        1: 'Difor, då me hev denne tenesta, etter som me hev fenge miskunn, so misser me ikkje modet,',
        2: 'men me hev avsagt dei skamlege løynvegar og gjeng ikkje fram med svikråd eller forfalskar Guds ord, men ved å kunngjera sanningi steller me oss fram for alle manns samvit for Guds åsyn.',
        3: 'Er då enn vårt evangelium dult, so er det dult millom deim som vert fortapte,',
        4: 'dei som guden til denne verdi hev blinda den vantruande hugen på, so ljoset frå evangeliet um Kristi herlegdom, han som er Guds bilæte, ikkje skal skina for deim.',
        5: 'For ikkje oss sjølve forkynnar me, men Kristus Jesus som Herre, men oss sjølve som dykkar tenarar for Jesu skuld.',
        6: 'For Gud, som sagde at ljos skulde skina fram or myrkret, han er den som og let det skina i våre hjarto, so kunnskapen um Guds herlegdom i Jesu Kristi åsyn skulde lysa fram frå oss.',
        7: 'Men me hev denne skatten i leirkjerald, so den rike krafti skal vera av Gud og ikkje av oss,',
        8: 'med di me stødt er i trengsla, men ikkje i stengsla, tvilande, men ikkje mistvilande,',
        9: 'forfylgde, men ikkje uppgjevne, nedslegne, men ikkje tynte,',
        10: 'alltid berande Jesu daude med oss i likamen, at og Jesu liv må verta openberra i vår likam;',
        11: 'for endå medan me liver, vert me alltid yvergjevne til dauden for Jesu skuld, at og Jesu liv må verta openberra i vårt døyelege kjøt.',
        12: 'Soleis er då dauden verksam i oss, men livet i dykk.',
        13: 'Men då me hev den same Ande med trui - etter det som stend skrive: «Eg trudde, difor tala eg» - so trur me og, difor talar me og,',
        14: 'då me veit, at han som vekte upp Herren Jesus, skal og vekkja oss upp med Jesus og stella oss fram med dykk.',
        15: 'For det hender alt for dykkar skuld, so nåden kann vinna so mange fleire og verka rikleg takk til Guds æra.',
        16: 'Difor misser me ikkje modet, men um og vårt ytre menneskje gjeng til grunns, so vert då det indre uppnya dag etter dag.',
        17: 'For vår kortvarande og lette trengsla verkar for oss ei æveleg nøgd av herlegdom i yvermål på yvermål,',
        18: 'med di me ikkje fester oss ved det synlege, men ved det usynlege; for det synlege er timelegt, men det usynlege ævelegt.',
    },
    5: {
        1: 'For me veit, at um vår likams jordiske hus vert nedrive, so hev me ein bygnad av Gud, eit hus som ikkje er gjort med hender, ævelegt i himmelen.',
        2: 'For ogso medan me er i dette huset, sukkar me, av di me stundar etter å verta yverklædde med vårt hus frå himmelen,',
        3: 'so sant me skal verta funne påklædde, ikkje nakne.',
        4: 'For me som er i denne hytta, sukkar under byrdi, av di me ikkje vil verta avklædde, men yverklædde, so det døyelege kann verta gløypt av livet.',
        5: 'Men den som laga oss just til dette, er Gud, som og gav oss Anden til pant.',
        6: 'Difor er me alltid frimodige, og veit, at so lenge me er heime i likamen, er me burte frå Herren;',
        7: 'for me ferdast i tru, men ikkje i syn.',
        8: 'Me er då frimodige og hyggjer oss meir til å koma burt frå likamen og koma heim til Herren.',
        9: 'Difor, anten me er heime eller burte, set me vår æra i å vera honom til hugnad.',
        10: 'For me skal alle verta openberra for Kristi domstol, so kvar kann få att det som er verka ved likamen, etter det han hev gjort, anten godt eller vondt.',
        11: 'Då me soleis kjenner otten for Herren, prøver me å vinna menneskje, men for Gud er me openberre; eg vonar og å vera openberr for dykkar samvit.',
        12: 'Ikkje rosar me oss sjølve atter for dykk, men me gjev dykk høve til å rosa dykk av oss, so de kann hava noko å setja imot deim som rosar seg av det dei er i det ytre og ikkje i hjarta.',
        13: 'For um me er frå vitet, so er det for Gud, og um me er med sans og samling, so er det for dykk.',
        14: 'For Kristi kjærleik tvingar oss,',
        15: 'då me hev gjort upp med oss sjølve at ein døydde for alle, difor hev dei alle døytt. Og han døydde for alle, so dei som liver, ikkje lenger skal liva for seg sjølve, men for honom som døydde og stod upp att for deim.',
        16: 'Difor kjenner me heretter ikkje nokon etter kjøtet; um me og hev kjent Kristus etter kjøtet, so kjenner me honom no ikkje lenger soleis.',
        17: 'Difor, um nokon er i Kristus, so er han ein ny skapning; det gamle hev forgjengest, sjå, alt hev vorte nytt!',
        18: 'Men alt dette er av Gud, som forlikte oss med seg sjølv ved Kristus og gav oss forlikstenesta.',
        19: 'For i Kristus forlikte Gud verdi med seg sjølv, so han ikkje tilreknar deim misgjerningarne deira, og hev lagt forliksordet ned i oss.',
        20: 'So er me då sendebod i staden for Kristus, liksom Gud sjølv gav fyreteljing gjenom oss. Me bed i staden for Kristus: Lat dykk forlika med Gud!',
        21: 'Den som ikkje visste av synd, hev han gjort til synd for oss, so me skal verta rettferdige for Gud i honom.',
    },
    6: {
        1: 'Men som medarbeidarar legg me dykk og på hjarta, at de ikkje til unyttes må taka imot Guds nåde.',
        2: 'For han segjer: «I den tid som meg tektest, bønhøyrde eg deg, og på frelse-dagen hjelpte eg deg.» Sjå, no er det tid som tekkjest vel, sjå, no er det frelse-dagen!',
        3: 'Og me gjev ikkje meinstøyt i nokon ting, so ikkje tenesta skal verta lasta,',
        4: 'men i alt viser me oss som Guds tenarar: ved stort tolmod, i trengslor, i naud, i hugverk,',
        5: 'under slag, i fengsel, i upprør, i træling, i vaking, i fasta,',
        6: 'ved reinleik, ved skynsemd, ved langmod, ved godleik, ved den Heilage Ande, ved uskrymta kjærleik,',
        7: 'med sannings ord, med Guds kraft, med rettferds våpn på høgre og vinstre sida;',
        8: 'i æra og vanæra, med lastord og lovord, som villførande og endå sannferdige,',
        9: 'som ukjende og endå velkjende, som døyande, og sjå, me liver! som dei som vert refste, men ikkje ihelslegne,',
        10: 'som syrgjande, men alltid glade, som fatige, men som endå gjer mange rike, som inkje havande og endå eigande alt.',
        11: 'Vår munn er upplaten mot dykk, korintarar, vårt hjarta hev vidga seg ut.',
        12: 'De hev ikkje trongt rom hjå oss, men det er trongt i dykkar hjarto.',
        13: 'Men til likt vederlag - eg talar som til born -: vidga de og ut dykkar hjarto!',
        14: 'Gakk ikkje i framandt ok med vantruande! For kva samlag hev rettferd med urett? eller kva samfund hev ljos med myrker?',
        15: 'Og kva samklang er det millom Kristus og Belial? eller kva lut hev ein truande med ein vantruande?',
        16: 'Og kva semja hev Guds tempel med avgudar? For me er den livande Guds tempel, som Gud sagde: «Eg vil bu og ferdast millom deim, og eg vil vera deira Gud, og dei skal vera mitt folk.»',
        17: '«Difor, gakk ut frå deim, og skil dykk frå deim, segjer Herren, og rør ikkje ved ureint, so skal eg taka imot dykk,',
        18: 'og eg skal vera dykk ein fader, og de skal vera meg søner og døtter, segjer Herren, den allmegtige.»',
    },
    7: {
        1: 'Sidan me då hev desse lovnaderne, mine kjære, so lat oss reinsa oss frå all ureinskap på kjøt og ånd og fullføra vår helging i Guds age!',
        2: 'Gjev oss rom! Ingen hev me gjort urett, ingen hev me skadt, ingen hev me gjenge for nær.',
        3: 'Ikkje til fordøming for dykk segjer eg dette; for eg hev sagt det fyrr, at de er i våre hjarto til å døy med oss og liva med oss.',
        4: 'Stor er mi tiltru til dykk, stor er mi ros yver dykk, eg er fyllt med trøyst, eg er ovrik på gleda i all vår trengsla.',
        5: 'For då me kom til Makedonia, hadde vårt kjøt ikkje heller ro, men me vart trengde på alle måtar; utantil var strid, innantil otte.',
        6: 'Men Gud, som trøystar det nedtrykte, han trøysta oss ved Titus’ koma,',
        7: 'men ikkje berre ved koma hans, men og ved den trøyst han var trøysta med yver dykk, med di han fortalde oss um dykkar lengting, dykkar gråt, dykkar ihuge for meg, so eg vart endå meir glad.',
        8: 'For um eg og i brevet gjorde dykk sorg, so angrar eg det ikkje, um eg og fyrr angra det; for eg ser at det brevet gjorde dykk sorg, um og berre ei stund.',
        9: 'No gled eg meg, ikkje for di de fekk sorg, men for di de fekk sorg til umvending; for de fekk sorg etter Gud, so de på ingen måte skulde hava skade av oss.',
        10: 'For sorgi etter Gud verkar umvending til frelsa, som ingen angrar; men sorgi til verdi verkar daude.',
        11: 'For sjå, dette same at de fekk sorg etter Gud, kor stor ihuge verka ikkje det hjå dykk, ja forsvar, ja harm, ja otte, ja lengting, ja brennhug, ja refsing! I alt viste de at de var reine i denne saki.',
        12: 'Um eg då og skreiv til dykk, so var det ikkje for hans skuld som gjorde urett, eller for hans skuld som leid urett, men for di at dykkar umhug for oss skulde verta openberra hjå dykk for Guds åsyn.',
        13: 'Difor er me trøysta. Og attåt vår trøyst kom den langt større gleda yver Titus’ gleda; for hans ånd er uppkveikt av dykk alle.',
        14: 'For um eg til honom hev uttala meg med ros yver dykk, hev eg ikkje vorte til skammar; men liksom me hev tala alt til dykk med sanning, so hev og vår ros til Titus vorte sanning.',
        15: 'Og hans kjærleik til dykk er endå sterkare, når han minnest lydnaden hjå dykk alle, korleis de tok imot honom med age og otte.',
        16: 'Eg gled meg yver at eg i alt kann lita på dykk.',
    },
    8: {
        1: 'Me kunngjer dykk, brør, den Guds nåde som er gjeven i kyrkjelydarne i Makedonia,',
        2: 'at endå dei var hardt røynde med trengsla, so hev deira rike gleda og deira djupe fatigdom i yverfullt mål verka hjå deim ein rikdom på ærleg kjærleik.',
        3: 'For dei var viljuge etter si råd, det vitnar eg, ja yver si råd, av eigen hug,',
        4: 'so dei inderleg bad oss um lov til å få vera med i hjelpi til dei heilage;',
        5: 'og dei gav ikkje berre soleis som me vona, men seg sjølve gav dei fyrst til Herren og so til oss ved Guds vilje,',
        6: 'so at me bad Titus, at liksom han fyrr hadde byrja, so skulde han og fullenda hjå dykk ogso dette kjærleiksverket.',
        7: 'Men liksom de er rike i alle måtar, på tru og tale og kunnskap og all umhug og på kjærleik som de hev vekt hjå oss, so vert no og rike i dette kjærleiksverket!',
        8: 'Ikkje som eit påbod segjer eg dette, men ved ihugen hjå dei andre vil eg og røyna sanningi av dykkar kjærleik.',
        9: 'For de kjenner vår Herre Jesu Kristi nåde, at han for dykkar skuld vart fatig, då han var rik, so de ved hans fatigdom skulde verta rike.',
        10: 'Og eg segjer mi meining um dette; for det er til gagn for dykk, som fyreåt, alt frå i fjor, byrja ikkje berre å verka, men og å vilja.',
        11: 'Men fullfør no og verket, so liksom hugen var til å vilja, soleis og fullføringi kann verta etter utkoma.',
        12: 'For er hugen der, so er han vellika etter det som han hev, ikkje etter det som han ikkje hev.',
        13: 'For det er ikkje for di at det skal vera lette for andre og trengsla for dykk, men at det skal vera jamnad:',
        14: 'dykkar yvermål vert til hjelp for deira trong i den noverande tid, at og deira yvermål kann verta til hjelp for dykkar trong, so det vert jamnad,',
        15: 'som de stend skrive: «Den som sanka mykje, fekk ikkje yverfyllt, og den som sanka lite, leid ingen skort.»',
        16: 'Men Gud vere takk, som inngav den same umhug for dykk i Titus’ hjarta!',
        17: 'for han tok gjerne imot mi påminning, ja, han er endå so ihuga at han fer sjølvminnt ut til dykk.',
        18: 'Og me sender og med honom den broren som hev ros hjå alle kyrkjelydarne for sitt arbeid i evangeliet,',
        19: 'ja, ikkje berre det, men han er og av kyrkjelydarne utvald til vår fylgjesmann med denne kjærleiksgåva, som er framkomi ved vår tenesta, til å fremja Herrens eigi æra og vårt framtak,',
        20: 'då me vil vara oss for at nokon skal lasta oss for noko som vedkjem denne rike gåva, som er framkomi ved vår tenesta,',
        21: 'og me legg vinn på det som godt er, ikkje berre for Herren, men og for menneskje.',
        22: 'Og me sender med deim vår bror, som me ofte på mange måtar hev funne ihuga, men no mykje meir ihuga ved si store tiltru til dykk.',
        23: 'Anten det då er tale um Titus, so er han min lagsmann og medarbeidar hjå dykk, eller um våre brør, so er dei sendemenner frå kyrkjelydarne, Kristi æra.',
        24: 'Syn deim då sanningi av dykkar kjærleik og av vår ros yver dykk, og det for augo på kyrkjelydarne!',
    },
    9: {
        1: 'For å skriva til dykk um hjelpi til dei heilage, det treng eg ikkje,',
        2: 'for eg kjenner dykkar viljuge hug, som eg rosar dykk for hjå makedonarane, med di eg segjer: «Akaia var ferdigt alt frå i fjor;» og ihugen dykkar tilskunda dei mange.',
        3: 'Men eg sender brørne, so ikkje vår ros yver dykk skal verta til inkjes i dette stykke, men at de, som eg sagde, skal vera ferdige,',
        4: 'so me - um eg ikkje skal segja de sjølve - ikkje skal få skam av denne tiltru, um det kjem makedonarar med meg og finn dykk uferdige.',
        5: 'Difor fann eg det naudsynlegt å telja brørne til å ganga i fyrevegen til dykk og fyreåt tilskipa gåva dykkar som fyrr var lova, so at ho kann vera ferdig som ei velsigning og ikkje som ei karg gåva.',
        6: 'Men det segjer eg: Den som sparleg sår, skal og sparleg hausta; og den som sår med velsigningar, skal og hausta med velsigningar.',
        7: 'Kvar gjeve som han set seg fyre i hjarta, ikkje med sut eller av tvang! For Gud elskar ein glad gjevar.',
        8: 'Og Gud er megtig til å gjeva dykk all nåde i rikt mål, so de i alle ting alltid kann hava all nøgd og vera rike til all god gjerning,',
        9: 'som skrive stend: «Han strøydde ut, han gav dei fatige, hans rettferd vert verande i all æva.»',
        10: 'Og han som gjev såmannen såkorn og brød til å eta, han skal og gjeva dykk sæde og gjera det rikelegt og gjeva vokster til frukterne av dykkar rettferd,',
        11: 'med di de i alt vert rike til all einfald kjærleik, som ved oss verkar takk til Gud.',
        12: 'For tenesta med denne hjelp utfyller ikkje berre det som vantar hjå dei heilage, men ber og rik frukt med takk til Gud ifrå mange,',
        13: 'då dei ved det sannrøynde hjartelag som denne hjelp syner, må prisa Gud for dykkar lydnad til å sanna Kristi evangelium, og for den einfalde truskapen i samfundet med deim og med alle,',
        14: 'med di dei og i bøn for dykk lengtar etter dykk for den Guds nåde som er so ovrik yver dykk.',
        15: 'Gud vere takk for si usegjelege gåva!',
    },
    10: {
        1: 'Men eg, Paulus, legg dykk på hjarta ved Kristi spaklynde og godlynde, eg som framfor augo på dykk er audmjuk hjå dykk, men djerv mot dykk når eg er fråverande;',
        2: 'men eg bed um, at eg ved mitt nærvære må sleppa å vera djerv med det frimod som eg tenkjer hugheilt å fara fram med imot sume, som dømer oss som um me ferdast etter kjøtet.',
        3: 'For um me ferdast i kjøtet, strider me då ikkje etter kjøtet.',
        4: 'For våre stridsvåpn er ikkje kjøtlege, men megtige for Gud til å støyta ned festningar,',
        5: 'med di me støyter ned tankebygningar og all høgd som reiser seg imot kunnskapen um Gud, og tek all tanke til fange under lydnaden mot Kristus',
        6: 'og er ferdige til å refsa all ulydnad, når dykkar lydnad fyrst er fullkomen.',
        7: 'De ser på det som ligg dykk for augo. Um nokon er viss med seg sjølv at han høyrer Kristus til, han døme då atter ifrå seg sjølv, at liksom han høyrer Kristus til, soleis me og.',
        8: 'For um eg og vil rosa meg noko meir av vår magt, som Herren gav oss til å uppbyggja dykk og ikkje til å riva ned, so vilde eg ikkje verta til skammar,',
        9: 'so ikkje eg skal synast liksom å vilde skræma dykk med brevi mine.',
        10: 'For brevi, segjer dei, er myndige og djerve, men det likamlege nærværet er veikt, og talen ikkje vyrd.',
        11: 'Den som segjer slikt, han tenkje då, at slike som me fråverande er i ord i brevi, slike er me og nærverande i gjerning.',
        12: 'For me vågar ikkje å rekna oss til eller likna oss med sume som rosar seg sjølve; men når desse mæler seg med seg sjølve og liknar seg med seg sjølve, er dei fåvituge.',
        13: 'Men me vil ikkje rosa oss til umåte, men etter målet av det umkverve som Gud hev sett oss til mål: at me skulde nå radt fram til dykk.',
        14: 'For me tøygjer oss ikkje utyver vårt mål, som um me ikkje hadde nått fram til dykk - for me er då komne fram til dykk med Kristi evangelium -',
        15: 'med di me ikkje rosar oss til umåte, av framandt arbeid, men hev von um, at når dykkar tru veks, skal me verta ovleg store hjå dykk etter vårt mål,',
        16: 'so me kann forkynna evangeliet på hi sida åt dykk, og ikkje i eit framandt umkverve rosa oss av det som alt er fullført.',
        17: 'Men den som rosar seg, rose seg i Herren!',
        18: 'For ikkje den som prisar seg sjølv, held prøva, men den som Herren prisar.',
    },
    11: {
        1: 'Gjev de vilde tola ein grand dårskap av meg! Jau, de skal tola meg.',
        2: 'For eg er åbryen på dykk med Guds åbryskap. For eg trulova dykk med ein mann, so eg kunde framstella ei rein møy for Kristus.',
        3: 'Men eg ottast for, at liksom ormen dåra Eva med si svikråd, soleis skal og dykkar tankar verta skadde og snudde burt frå den einfalde truskapen mot Kristus.',
        4: 'For um det kjem ein og forkynner ein annan Jesus, som me ikkje hev forkynt, eller de fær ein framand ande, som de ikkje fyrr hev fenge, eller eit framandt evangelium, som de ikkje fyrr hev motteke, so vil de tola det godt!',
        5: 'For eg tenkjer at eg ikkje i nokon ting er mindre mann enn dei ovstore apostlarne;',
        6: 'men um eg enn er ulærd i talen, er eg det då ikkje i kunnskapen; me hev tvert imot alltid synt dykk honom i alle stykke.',
        7: 'Eller gjorde eg synd, då eg audmykte meg sjølv so de kunde verta upphøgde, med di eg forkynte dykk Guds evangelium for inkje?',
        8: 'Andre kyrkjelydar hev eg skattlagt, med di eg tok løn til dykkar tenesta, og då eg var hjå dykk og noko vanta meg, var eg ingen til tyngsla;',
        9: 'for når eg vanta noko, hjelpte brørne som kom frå Makedonia, og i alt vara eg meg for å falla dykk til tyngsla.',
        10: 'So visst som Kristi sanning er i meg, so skal denne ros ikkje takast frå meg i Akaia-bygderne!',
        11: 'Kvifor då? av di eg ikkje elskar dykk? Det veit Gud!',
        12: 'Men det eg gjer, det vil eg og gjera sidan, so eg kann avskjera deim tilhøve, som søkjer tilhøve, so dei må verta funne liksom me i det som dei rosar seg av.',
        13: 'For desse er falske apostlar, svikfulle arbeidarar, som skaper seg til liksom dei var Kristi apostlar.',
        14: 'Og det er ikkje underlegt, for Satan sjølv skaper seg um til ein ljosengel;',
        15: 'difor er det ikkje noko stort um hans tenarar og skaper seg um til rettferds tenarar; men deira ende skal høva til deira verk.',
        16: 'Atter segjer eg: Ingen halde meg for å vera uvitug, men um de gjer det, so tak då imot meg, um og som ein uvitug, so eg og må kunna rosa meg ein grand!',
        17: 'Det eg her talar, talar eg ikkje etter Herrens vilje, men liksom i dårskap i denne tillitsame ros.',
        18: 'Sidan mange rosar etter kjøtet, so vil eg og rosa meg.',
        19: 'For de toler gjerne uvitingarne, de som er so kloke.',
        20: 'For de toler det, um nokon gjer dykk til trælar, um nokon et dykk upp, um nokon fangar dykk, um nokon upphøgjer seg yver dykk, um nokon slær dykk i andlitet.',
        21: 'Med skam segjer eg det, av di me hev vore veike; men det som nokon er djerv i - eg talar i dårskap - det er eg og djerv i.',
        22: 'Er dei hebræarar? eg og. Er dei israelitar? eg og. Er dei Abrahams ætt? eg og.',
        23: 'Er dei Kristi tenarar? - eg talar som ein galen mann -: eg er det endå meir. Eg hev havt større stræv, fenge fleire slag, vore oftare i fengsel, ofte i livsfåre.',
        24: 'Av jødarne hev eg fem gonger fenge fyrti slag so nær som eitt.',
        25: 'Tri gonger vart eg hudflengd, ein gong steina, tri gonger leid eg skipbrot; eg hev vore eit døger i djupet.',
        26: 'Ofte var eg på ferder, i fårar i elvar, i fårar millom røvarar, i fårar millom landsmenner, i fårar millom heidningar, i fårar i by, i fårar i øydemark, i fårar på hav, i fårar millom falske brør,',
        27: 'i strev og møda, ofte i nattevoka, i svolt og torste, ofte fastande, frosen og naken;',
        28: 'umfram alt det andre hev eg endå det daglege tillaup, umsuti for alle kyrkjelydarne.',
        29: 'Kven er veik utan at eg vert veik? Kven vert avstygd utan at det brenn i meg?',
        30: 'Um eg endeleg skal rosa meg, so vil eg rosa meg av det som høyrer mi vanmagt til.',
        31: 'Gud og vår Herre Jesu Kristi Fader, som er velsigna i all æva, han veit at eg ikkje lyg!',
        32: 'I Damaskus let kong Aretas’ landshovding vakta damaskenarbyen, då han vilde gripa meg;',
        33: 'og gjenom ein glugg i muren vart eg fira ned i ei korg og slapp ut or hans hender.',
    },
    12: {
        1: 'Eg lyt rosa meg, endå det ikkje er gagnlegt, men eg kjem no til syner og openberringar av Herren.',
        2: 'Eg kjenner eit menneskje i Kristus - um han var i likamen, det veit eg ikkje, eller utanfor likamen, det veit eg ikkje, Gud veit det - ein som for fjortan år sidan vart rykt inn i den tridje himmelen.',
        3: 'Og eg kjenner dette menneskjet, - um han var i likamen eller utanfor likamen, det veit eg ikkje, Gud veit det -',
        4: 'han vart rykt inn i Paradis og høyrde usegjelege ord, som det ikkje er unnt eit menneskje å tala.',
        5: 'Av dette vil eg rosa meg, men av meg sjølv vil eg ikkje rosa meg, utan av mi vanmagt.',
        6: 'For um eg vil rosa meg, vert eg ikkje uvitug, for sanning kjem eg til å segja; men eg let det vera, so ingen skal tenkja større um meg, enn som han ser meg eller høyrer av meg.',
        7: 'Og for at eg ikkje skal ovmoda meg av dei høge openberringar, so er det gjeve meg ein tagg i kjøtet, ein Satans engel, at han skal slå meg, so eg ikkje skal ovmoda meg.',
        8: 'Um denne bad eg Herren tri gonger, at han måtte vika frå meg.',
        9: 'Og han sagde til meg: «Min nåde er nok åt deg; for mi kraft vert fullenda i vanmagt.» Helst vil eg difor rosa meg av mi vanmagt, so Kristi kraft kann bu i meg.',
        10: 'Difor er eg vel til mods midt i vanmagt, i valdsverk, i naud, i forfylgjing, i trengslor for Kristi skuld. For når eg er vanmegtig, då er eg sterk.',
        11: 'Eg hev vorte uvitug; de hev tvinga meg til det; for eg skulde havt lovord av dykk; eg var ikkje i noko mindre mann enn dei ovstore apostlar, endå eg er ingen ting.',
        12: 'Ein apostels teikn vart gjorde hjå dykk i alt tolmod, med teikn og under og kraftige verk.',
        13: 'For kva er det som de vart haldne ringare i enn dei andre kyrkjelydar, utan at eg sjølv ikkje var dykk til tyngsla? tilgjev meg denne uretten!',
        14: 'Sjå, tridje gongen er eg buen til å koma til dykk og skal ikkje vera dykk til tyngsla. For eg søkjer ikkje dykkar gods, men dykk sjølve; for borni skal ikkje sanka skattar til foreldri, men foreldri til borni.',
        15: 'Men eg vil gjerne ofra, ja, verta ofra for sjælerne dykkar, um eg enn vert mindre elska di meir eg elskar dykk.',
        16: 'Men lat so vera at eg ikkje var dykk til tyngsla, men kann henda eg var svikfull og tok dykk med list?',
        17: 'Søkte eg vel vinning av dykk ved nokon av deim som eg sende til dykk?',
        18: 'Eg talde Titus til og sende med honom bror vår. Hev Titus søkt vinning av dykk? For me ikkje fram i den same ånd? ikkje i dei same fotfar?',
        19: 'Longe hev de tenkt at det er for dykk me forsvarar oss. Nei, det er for Guds åsyn me talar i Kristus. Men alt til dykkar uppbyggjing, mine kjære!',
        20: 'For eg ottast for, at når eg kjem, skal eg ikkje finna dykk slike som eg vil, og at eg skal verta funnen av dykk slik som de ikkje vil - at der skal vera kiv, ovund, vreide, stridssykja, baktale, drøsor, ovmod, utstyr,',
        21: 'at når eg kjem, skal min Gud atter audmykja meg hjå dykk, og eg skal syrgja yver mange av deim som fyrr synda og ikkje hev umvendt seg frå den ureinskap og lauslivnad og used som dei dreiv.',
    },
    13: {
        1: 'Det er no tridje gongen eg kjem til dykk. Ved tvo og tri vitnemål skal kvar sak standa fast.',
        2: 'Eg hev sagt det fyreåt og segjer det fyreåt, liksom då eg var nærverande andre gongen, soleis og no då eg er fråverande, til deim som fyrr synda og til alle dei andre, at når eg no kjem att, vil eg ikkje spara,',
        3: 'sidan de krev eit prov på at Kristus talar i meg, han som ikkje er vanmegtig hjå dykk, men er sterk imillom dykk.',
        4: 'For um han og vart krossfest i vanmagt, so lever han i Guds kraft; for me og er vanmegtige i honom, men me skal liva med honom i Guds kraft hjå dykk.',
        5: 'Ransaka dykk sjølve, um de er i trui! prøv dykk sjølve! eller kjenner de ikkje dykk sjølve, at Jesus Kristus er i dykk, utan so er at de ikkje held prøva?',
        6: 'Men eg vonar at de skal kjenna, at me ikkje er dei som ikkje held prøva.',
        7: 'Men me bed til Gud, at de ikkje må gjera noko vondt, ikkje for di at me skal visa oss å halda prøva, men at de skal gjera det gode, men me vera som dei som ikkje held prøva.',
        8: 'For me kann ikkje noko imot sanningi, men berre for sanningi.',
        9: 'For me gled oss når me er vanmegtige, men de sterke; men dette bed me og um, at de må verta fullkomne.',
        10: 'Difor skriv eg dette fråverande, so eg, når eg er nærverande, ikkje skal trenga til å vera streng etter den magt som Herren hev gjeve meg til uppbyggjing, ikkje til nedriving.',
        11: 'Elles, brør, gled dykk, vert fullkomne, lat dykk påminna, ver samlyndte, ver fredsame, so skal kjærleiks og freds Gud vera med dykk.',
        12: 'Helsa kvarandre med ein heilag kyss! Alle dei heilage helsar dykk.',
        13: 'Herren Jesu Kristi nåde og Guds kjærleik og den Heilage Andens samfund vere med dykk alle!',
    },
}
